def maxScore(nums: List[int]) -> int:
    def get_gcd(a, b):
        return math.gcd(a, b)

    def get_lcm(a, b):
        if a == 0 or b == 0:
            return 0
        return abs(a * b) // math.gcd(a, b)

    n = len(nums)
    if n == 0:
        return 0
    if n == 1:
        return nums[0] * nums[0]

    def calculate_score(arr):
        if not arr:
            return 0
        current_gcd = arr[0]
        current_lcm = arr[0]
        for i in range(1, len(arr)):
            current_gcd = get_gcd(current_gcd, arr[i])
            current_lcm = get_lcm(current_lcm, arr[i])
        return current_gcd * current_lcm

    # Initial score without removing any element
    max_score = calculate_score(nums)

    # Try removing each element one by one
    for i in range(n):
        remaining = nums[:i] + nums[i+1:]
        if not remaining:
            continue
        score = calculate_score(remaining)
        if score > max_score:
            max_score = score

    return max_score
