                for k in range(max(0, i - m + 1), min(n, i + 1)):
                    if str1[k] == 'F':
                        # If all chars in current window [k, k+m-1] are filled
                        # and they match str2, it's invalid.
                        window_match = True
                        fully_filled = True
                        for j in range(m):
                            idx = k + j
