import functools

def minCost(nums: list[int]) -> int:
    n = len(nums)
    # dp(i, extra_idx): i is the first index in nums that hasn't been "processed" 
    # (either removed or skipped). extra_idx is an index < i that was skipped.
    @functools.lru_cache(None)
    def solve(i, j):
        # The set of available elements at the front are those with indices:
        # {j if j != -1 else None} union {k for k in range(i, n)}
        available = []
        if j != -1:
            available.append(j)
        for k in range(i, n):
            if k != j:
                available.append(k)
                if len(available) == 3:
                    break

        # Rule: If fewer than three elements remain in nums total (not just the first three),
        # remove all remaining with cost of max.
        # Actually, the problem says "If fewer than three elements remain in nums".
        # This means we check the count of all indices >= i and j.
        total_remaining = 0
        if j != -1: total_remaining += 1
        for k in range(i, n):
            if k != j: total_remaining += 1

        if total_remaining < 3:
            res = max([nums[idx] for idx in available]) if available else 0
            return res

        # Otherwise, pick two from the first three elements.
        pool = available[:3]
        res = float('inf')
        for a in range(len(pool)):
            for b in range(a + 1, len(pool)):
                p1, p2 = pool[a], pool[b]
                cost = max(nums[p1], nums[p2])

                # The one remaining from the first three becomes the new extra.
                new_j = -1
                for p in pool:
                    if p != p1 and p != p2:
                        new_j = p
                        break

                # New i is the smallest index >= i that was not removed or skipped.
                new_i = i
                while new_i < n and (new_i == p1 or new_i == p2 or new_i == j):
                    new_i += 1

                # If we picked something from the future (index > i), 
                # but an index < i was skipped, that skipped one is still available.
                # However, our 'j' logic already tracks any skipped element < new_i.
                res = min(res, cost + solve(new_i, new_j))
        return res

