    # q+1 < r => r >= q+2
    # r+1 < s => s >= r+2

    for q in range(2, n - 3):
        p_counts[nums[q-2]] += 1
        s_counts = collections.Counter()
        # For a fixed q and r, we need counts of p in [0, q-2] 
