        # At the start of the r loop, r = n - 3.
        # We want s_counts to represent nums[n-1 : n].
        if n - 1 < n:
            s_counts[nums[n-1]] += 1

        for r in range(n - 3, q + 1, -1):
            if r >= q + 2:
